String eventLog;
BLEScan* bleScanner = nullptr;

// ---------------------------------------------------------
// Logging
// ---------------------------------------------------------

void logEvent(String msg) {
  String line = "[" + String(millis() / 1000) + "s] " + msg + "\n";
  Serial.print(line);
  eventLog += line;

  // Prevent runaway RAM use
  if (eventLog.length() > 12000) {
    eventLog.remove(0, 4000);
  }
}

