  p += "Uptime: " + String(millis()/1000) + " sec<br>";
  p += "Free heap: " + String(ESP.getFreeHeap()) + " bytes<br>";
  p += "</div>";

  p += "<div class='card'>";
  p += "<h2>Tools</h2>";
  p += "<p><a href='/console'>Web Console</a></p>";
  p += "<p><a href='/wifi'>Wi-Fi Survey</a></p>";
