// ---------------------------------------------------------
// Wi-Fi survey
// ---------------------------------------------------------

void handleWiFi() {
  logEvent("Wi-Fi scan started");

  int n = WiFi.scanNetworks(false,true);

  String p = header("Wi-Fi Survey");
  p += "<h1>Wi-Fi Survey</h1>";
  p += nav();

  p += "<div class='card'>";
  p += "<b>Networks found: " + String(n) + "</b>";
  p += "<p><a href='/wifi'>Rescan</a></p>";

  p += "<table>";
  p += "<tr><th>SSID</th><th>dBm</th><th>CH</th><th>Security</th><th>BSSID</th></tr>";

  for(int i=0;i<n;i++) {
    String name = WiFi.SSID(i);
    if(name.length()==0) name="[hidden]";

    p += "<tr><td>" + name + "</td>";
    p += "<td>" + String(WiFi.RSSI(i)) + "</td>";
    p += "<td>" + String(WiFi.channel(i)) + "</td>";
    p += "<td>" + securityName(WiFi.encryptionType(i)) + "</td>";
    p += "<td>" + WiFi.BSSIDstr(i) + "</td></tr>";
  }

  p += "</table></div></body></html>";

  WiFi.scanDelete();
  logEvent("Wi-Fi scan completed");

  server.send(200,"text/html",p);
}

// ---------------------------------------------------------
// BLE
// ---------------------------------------------------------

void handleBLE() {
  logEvent("BLE scan started");

  BLEScanResults results = bleScanner->start(4,false);

  String p = header("BLE Scanner");
  p += "<h1>BLE Scanner</h1>";
  p += nav();

  p += "<div class='card'>";
  p += "<b>Advertisements found: ";
  p += String(results.getCount());
  p += "</b>";

  p += "<p><a href='/ble'>Rescan</a></p>";

  p += "<table>";
  p += "<tr><th>Name</th><th>Address</th><th>RSSI</th></tr>";

  for(int i=0;i<results.getCount();i++) {
    BLEAdvertisedDevice d = results.getDevice(i);

    String name = d.haveName()
      ? String(d.getName().c_str())
      : "[unnamed]";

    p += "<tr><td>";
    p += name;
    p += "</td><td>";
    p += String(d.getAddress().toString().c_str());
    p += "</td><td>";
    p += String(d.getRSSI());
    p += "</td></tr>";
  }

  p += "</table></div></body></html>";

  bleScanner->clearResults();

  logEvent("BLE scan completed");
  server.send(200,"text/html",p);
}

