// ---------------------------------------------------------
// Command console
// ---------------------------------------------------------

String executeCommand(String cmd) {
  cmd.trim();

  if(cmd=="help") {
    return
      "help\n"
      "status\n"
      "uptime\n"
      "heap\n"
      "wifi scan\n"
      "ble scan\n"
      "config\n"
      "log\n"
      "clearlog\n"
      "reboot\n";
  }

  if(cmd=="status") {
    String s;
    s += FW_VERSION;
    s += "\nAP: " + apSSID;
    s += "\nIP: " + WiFi.softAPIP().toString();
    s += "\nClients: " + String(WiFi.softAPgetStationNum());
    s += "\nHeap: " + String(ESP.getFreeHeap());
    return s;
  }

  if(cmd=="uptime")
    return String(millis()/1000) + " seconds";

  if(cmd=="heap")
    return String(ESP.getFreeHeap()) + " bytes";

  if(cmd=="wifi scan")
    return "Open /wifi to perform Wi-Fi survey.";

  if(cmd=="ble scan")
    return "Open /ble to perform BLE scan.";

  if(cmd=="config") {
    return
      "SSID: " + apSSID +
      "\nHostname: " + hostname;
  }

  if(cmd=="log")
    return eventLog;

  if(cmd=="clearlog") {
    eventLog="";
    return "Log cleared.";
  }

  if(cmd=="reboot") {
    server.send(200,"text/plain","Rebooting...");
    delay(500);
    ESP.restart();
    return "";
  }

  return "Unknown command. Type: help";
}

void handleConsole() {
  String output="";

  if(server.hasArg("cmd")) {
    String cmd=server.arg("cmd");
    logEvent("Console: " + cmd);
    output=executeCommand(cmd);
  }

  String p=header("Console");

  p+="<h1>LOW-SPEC Console</h1>";
  p+=nav();

  p+=R"rawliteral(
<div class="card">
<form method="GET">
<input
 name="cmd"
 autofocus
 autocomplete="off"
 placeholder="help"
 style="width:70%">
<button type="submit">Run</button>
</form>
<pre>
)rawliteral";

  p+=output;
  p+="</pre></div></body></html>";

  server.send(200,"text/html",p);
}

// ---------------------------------------------------------
// Configuration
// ---------------------------------------------------------

void handleConfig() {
  if(server.method()==HTTP_POST) {

    String newSSID=server.arg("ssid");
    String newPass=server.arg("pass");
    String newHost=server.arg("host");

    if(newSSID.length()>0)
      apSSID=newSSID;

    // WPA2 requires at least 8 characters
    if(newPass.length()>=8)
      apPass=newPass;

    if(newHost.length()>0)
      hostname=newHost;

    prefs.begin("lowspec",false);
    prefs.putString("ssid",apSSID);
    prefs.putString("pass",apPass);
    prefs.putString("host",hostname);
    prefs.end();

    logEvent("Configuration saved");

    server.send(
      200,
      "text/html",
      "<h2>Saved.</h2>"
      "<p>Reboot required.</p>"
      "<p><a href='/'>Home</a></p>"
    );

    return;
  }

  String p=header("Configuration");
  p+="<h1>Configuration</h1>";
  p+=nav();

  p+=R"rawliteral(
<div class="card">
<form method="POST">

<label>AP Name</label><br>
<input name="ssid" value="
)rawliteral";

  p+=apSSID;

  p+=R"rawliteral(
"><br>

<label>AP Password</label><br>
<input name="pass" type="password"
placeholder="leave unchanged"><br>

<label>Hostname</label><br>
<input name="host" value="
)rawliteral";

  p+=hostname;

  p+=R"rawliteral(
"><br><br>

<button type="submit">Save</button>

</form>
</div>
</body></html>
)rawliteral";

  server.send(200,"text/html",p);
}

