// ---------------------------------------------------------
// Setup
// ---------------------------------------------------------

void setup() {
  Serial.begin(115200);
  delay(300);

  bool recovery =
    digitalRead(BOOT_PIN)==LOW;

  prefs.begin("lowspec",true);

  if(!recovery) {
    apSSID=prefs.getString("ssid","LOW-SPEC");
    apPass=prefs.getString("pass","lowspec32");
    hostname=prefs.getString("host","low-spec");
  }

  prefs.end();

  if(recovery) {
    apSSID="LOW-SPEC";
    apPass="lowspec32";
    hostname="low-spec";
  }

  WiFi.mode(WIFI_AP_STA);
  WiFi.setHostname(hostname.c_str());
  WiFi.softAP(apSSID.c_str(),apPass.c_str());

  BLEDevice::init("");
  bleScanner=BLEDevice::getScan();
  bleScanner->setActiveScan(false);

  server.on("/",HTTP_GET,handleHome);
  server.on("/wifi",HTTP_GET,handleWiFi);
  server.on("/ble",HTTP_GET,handleBLE);
  server.on("/system",HTTP_GET,handleSystem);

  server.on("/console",HTTP_GET,handleConsole);

  server.on("/config",HTTP_GET,handleConfig);
  server.on("/config",HTTP_POST,handleConfig);

  server.on("/update",HTTP_GET,handleUpdatePage);

  server.on(
    "/update",
    HTTP_POST,

    [](){
      bool failed=Update.hasError();

      server.send(
        200,
        "text/plain",
        failed
          ? "UPDATE FAILED"
          : "UPDATE SUCCESS - REBOOTING"
      );

      if(!failed) {
        delay(1000);
        ESP.restart();
      }
    },

    [](){
      HTTPUpload& upload=server.upload();

      if(upload.status==UPLOAD_FILE_START) {

        logEvent(
          "OTA start: " +
          upload.filename
        );

        if(!Update.begin(UPDATE_SIZE_UNKNOWN)) {
          Update.printError(Serial);
        }
      }

      else if(upload.status==UPLOAD_FILE_WRITE) {

        if(
          Update.write(
            upload.buf,
            upload.currentSize
          )
          != upload.currentSize
        ) {
          Update.printError(Serial);
        }
      }

      else if(upload.status==UPLOAD_FILE_END) {

        if(Update.end(true))
          logEvent("OTA completed");
        else
          Update.printError(Serial);
      }
    }
  );

  server.begin();

  logEvent(FW_VERSION);
  logEvent("AP: " + apSSID);
  logEvent(
    "IP: " +
    WiFi.softAPIP().toString()
  );
}

void loop() {
  server.handleClient();
}
